const test=require('node:test'),assert=require('node:assert/strict'),L=require('./log-data'),M=require('./model');
const fresh=()=>M.initial();
const metadata={platform:'Web',device:'browser-demo',version:'1.0',build:'web-1',begin:'2026-10-20T10:40',end:'2026-10-20T10:45'};
const good=JSON.stringify({timestamp:'2026-10-20T10:42:00+08:00',level:'ERROR',module:'BrowserAuth',message:'request timeout',requestId:'web-42',file:'src/auth.ts',line:18});
function imported(text=good,format='auto',policy='strict'){let s=fresh(),i=s.issues[0],a=L.importFiles(s,i,{...metadata,files:[{name:'web.jsonl',text}],format,policy}).asset;return {s,i,a,r:a.runs[0]};}
function done(a,r){for(let n=0;n<3;n++)L.advance(a,r);return r;}
test('导入只创建已接收文件和待解析批次，不虚构推送或提前发布任务',()=>{let {i,a,r}=imported();assert.equal(r.status,'待解析');assert.equal(r.task,null);assert.equal(i.requests.length,0);assert.equal(M.tasks(i).length,0);assert.equal(a.files[0].text,good);});
test('Web JSONL 解析保留真实事件和 requestId，上传内容不执行',()=>{let {a,r,i}=imported();done(a,r);assert.equal(r.status,'完成');assert.equal(r.records[0].requestId,'web-42');assert.equal(r.records[0].file,'src/auth.ts');assert.equal(r.records[0].sourceVerified,false);assert.equal(r.records[0].scene,'generic');assert.equal(M.tasks(i)[0].records[0].content.includes('timeout'),true);});
test('严格模式失败时显示错误行，不创建可查任务',()=>{let {a,r}=imported(good+'\n{bad json');done(a,r);assert.equal(r.status,'解析失败');assert.equal(r.task,null);assert.equal(r.errors[0].line,2);});
test('仅重新解析原文件：错误行跳过后发布部分结果，原失败批次保持不变',()=>{let {a,r,i}=imported(good+'\n{bad json');done(a,r);let old=JSON.stringify(r),next=L.reparse(a,{format:'jsonl',policy:'skip'});done(a,next);assert.equal(next.status,'部分成功');assert.equal(next.records.length,1);assert.equal(JSON.stringify(r),old);assert.equal(a.files[0].text,good+'\n{bad json');assert.equal(i.requests.length,0);assert.equal(M.tasks(i).length,1);});
test('解析格式修正后成功；重复点击重解析合并进行中批次',()=>{let {a,r}=imported(good,'text');done(a,r);assert.equal(r.status,'解析失败');let n=L.reparse(a,{format:'jsonl',policy:'strict'});assert.equal(L.reparse(a,{format:'auto',policy:'skip'}).id,n.id);done(a,n);assert.equal(n.status,'完成');});
test('成功后的新解析批次保留旧任务及原事件快照',()=>{let {a,r,i}=imported();done(a,r);let old=JSON.stringify(M.tasks(i)[0]),next=L.reparse(a,{format:'auto',policy:'strict'});done(a,next);assert.equal(M.tasks(i).length,2);assert.equal(JSON.stringify(M.tasks(i)[0]),old);assert.notEqual(r.task,next.task);});
test('重复导入同一工单同文件合并，空文件和超限文件不写入状态',()=>{let {s,i,a}=imported();assert.equal(L.importFiles(s,i,{...metadata,files:[{name:'web.jsonl',text:good}]}).duplicate,true);assert.equal(i.logAssets.length,1);assert.throws(()=>L.importFiles(s,i,{...metadata,files:[{name:'bad.exe',text:good}]}),/格式/);assert.throws(()=>L.importFiles(s,i,{...metadata,files:[{name:'empty.log',text:'  '}]}),/空/);assert.throws(()=>L.importFiles(s,i,{...metadata,files:[{name:'big.log',text:'x'.repeat(300000)}]}),/上限/);assert.equal(i.logAssets[0].id,a.id);});
test('Web 样例使用 TSX 源码与自己的日志，不借用 Native Swift 事件',()=>{let s=fresh(),i=s.issues[0],a=L.webSample(s,i);done(a,a.runs[0]);assert.equal(a.platform,'Web');assert.equal(a.runs[0].records.length,5);assert.match(a.runs[0].records[4].code,/setLoading/);assert.match(a.runs[0].records[4].file,/tsx/);assert.equal(a.runs[0].records[4].scene,'login');});
test('多文件错误归属到文件和行号，跳过全部坏行仍不能发布空任务',()=>{let {a,r}=imported('{bad');done(a,r);let n=L.reparse(a,{format:'jsonl',policy:'skip'});done(a,n);assert.equal(n.status,'解析失败');assert.equal(n.task,null);assert.equal(n.errors[0].file,'web.jsonl');});
test('JSON 数组、BOM 和多文件按事件时间排序，字段作为数据保留',()=>{let s=fresh(),i=s.issues[0];let a=L.importFiles(s,i,{...metadata,files:[{name:'late.json',text:'\uFEFF'+JSON.stringify([{time:'2026-10-20T10:43:00+08:00',message:'<img src=x onerror=alert(1)>',module:'<b>module</b>'}])},{name:'early.jsonl',text:good}]}).asset;done(a,a.runs[0]);assert.equal(a.runs[0].records.length,2);assert.equal(a.runs[0].records[0].module,'BrowserAuth');assert.match(a.runs[0].records[1].content,/<img/);});
test('空 JSON 数组不给空索引，并记录明确失败原因',()=>{let {a,r}=imported('[]');done(a,r);assert.equal(r.status,'解析失败');assert.equal(r.task,null);assert.match(r.errors[0].message,/有效事件/);});
test('导入与重解析不清除旧工单、旧请求和已有调查材料',()=>{let s=fresh(),i=s.issues[0];i.evidence=[{id:'existing',text:'保留材料'}];i.investigation={rounds:[{id:'R1',status:'done'}]};M.create(s,i,{device:i.device,begin:i.begin,end:i.end,types:['应用日志'],budget:32,ttl:30,notify:true});let before=JSON.stringify({requests:i.requests,evidence:i.evidence,investigation:i.investigation});let a=L.webSample(s,i);done(a,a.runs[0]);done(a,L.reparse(a,{format:'auto',policy:'strict'}));assert.equal(JSON.stringify({requests:i.requests,evidence:i.evidence,investigation:i.investigation}),before);});
test('声明时间外的事件保留但给出范围警示',()=>{let {a,r}=imported(good);a.begin='2026-10-19T10:40';a.end='2026-10-19T10:45';done(a,r);assert.equal(r.status,'完成');assert.match(r.warnings[0],/超出/);});
test('普通导入的第 5 条事件不会被当作固定登录状态日志',()=>{let AI=require('./ai-model'),s={rounds:[],context:[{id:'imported-L5',kind:'log',task:'imported',index:4,scene:'generic',text:'checkout failed'}],hypotheses:[],revision:0};let r=AI.start(s,'排查这些导入日志');AI.finish(s,r.id);assert.equal(s.hypotheses.length,0);assert.match(r.answer.body,/导入材料|导入记录/);assert.equal(r.answer.codeConfirmed,false);});
test('导入后新完成的回捞仍能作为最新任务，不被导入数组覆盖顺序',()=>{let {s,i,a,r}=imported();done(a,r);r.createdAt='2026-10-20T01:00:00Z';let capture=M.create(s,i,{device:i.device,begin:i.begin,end:i.end,types:['应用日志'],budget:32,ttl:30,notify:true}).request;capture.createdAt='2026-10-20T02:00:00Z';for(let n=0;n<5;n++)M.advance(capture);assert.equal(M.tasks(i).at(-1).id,capture.task);assert.equal(M.tasks(i)[0].id,r.task);});
